import Foundation

/// Where a registrable domain begins: the Public Suffix List (`PublicSuffixList+Rules.swift`,
/// regenerated by `scripts/update_public_suffix_list.py`). `login.example.co.uk` and
/// `www.example.co.uk` share the registrable domain `example.co.uk`; `alice.github.io` and
/// `bob.github.io` do not (`github.io` is a suffix under which different people own names).
///
/// The algorithm is the list's own (https://publicsuffix.org/list/): the matching exception rule
/// wins, else the matching rule with the most labels, else `*`; the registrable domain is the
/// public suffix plus one label. Host names are compared in ASCII (Punycode), as WebKit reports them.
public enum PublicSuffixList {
    private struct Rules {
        var exact: Set<String> = []
        /// `*.ck` stored as `ck`.
        var wildcard: Set<String> = []
        /// `!www.ck` stored as `www.ck`.
        var exception: Set<String> = []
    }

    private static let rules: Rules = {
        var rules = Rules()
        for line in rulesText.split(separator: "\n") {
            if line.hasPrefix("!") {
                rules.exception.insert(String(line.dropFirst()))
            } else if line.hasPrefix("*.") {
                rules.wildcard.insert(String(line.dropFirst(2)))
            } else {
                rules.exact.insert(String(line))
            }
        }
        return rules
    }()

    /// `example.co.uk` for `login.example.co.uk`; nil for an IP address, a public suffix itself
    /// (`co.uk`, `github.io`) or a single label (`localhost`).
    public static func registrableDomain(of host: String) -> String? {
        var host = host.lowercased()
        if host.hasSuffix(".") { host.removeLast() }
        guard !host.isEmpty, !host.hasPrefix("."), !host.contains(".."), !isIPAddress(host) else { return nil }
        let labels = host.split(separator: ".").map(String.init)
        let suffixLength = publicSuffixLength(labels)
        guard suffixLength < labels.count else { return nil }
        return labels.suffix(suffixLength + 1).joined(separator: ".")
    }

    /// How many trailing labels of `labels` are the public suffix.
    private static func publicSuffixLength(_ labels: [String]) -> Int {
        let rules = Self.rules
        // An exception rule wins whatever its length: its public suffix is the rule minus its first label.
        for start in labels.indices {
            if rules.exception.contains(labels[start...].joined(separator: ".")) {
                return labels.count - start - 1
            }
        }
        // Longest first: the first rule that matches has the most labels.
        for start in labels.indices {
            let candidate = labels[start...].joined(separator: ".")
            if rules.exact.contains(candidate) { return labels.count - start }
            if start + 1 < labels.count, rules.wildcard.contains(labels[(start + 1)...].joined(separator: ".")) {
                return labels.count - start
            }
        }
        return 1 // the default rule `*`
    }

    private static func isIPAddress(_ host: String) -> Bool {
        if host.contains(":") { return true } // IPv6, bracketed or not
        let labels = host.split(separator: ".", omittingEmptySubsequences: false)
        return labels.count == 4 && labels.allSatisfy { !$0.isEmpty && $0.allSatisfy(\.isNumber) }
    }
}
